import assert from "node:assert/strict";
import { execFileSync, spawn } from "node:child_process";
import { createServer } from "node:http";
import { copyFileSync, mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

const root = "C:\\Users\\Lauri\\AppData\\Local\\ChatGPTMcpClean";
const sourceState = join(root, ".state", "front-door");
const temporary = mkdtempSync(join(tmpdir(), "shell-mcp-real-route-proof-"));
const configPath = join(temporary, "active-backend.json");
const processRoutesPath = join(temporary, "process-routes.json");
const staticRoutesPath = join(temporary, "static-routes.json");
const requestLogPath = join(temporary, "request.jsonl");
let frontDoor;

const sleep = (ms) => new Promise((resolveSleep) => setTimeout(resolveSleep, ms));
async function unusedPort() {
  const server = createServer();
  await new Promise((resolveListen) => server.listen(0, "127.0.0.1", resolveListen));
  const port = server.address().port;
  await new Promise((resolveClose) => server.close(resolveClose));
  return port;
}

async function waitHealth(origin) {
  for (let attempt = 0; attempt < 240; attempt += 1) {
    try {
      const response = await fetch(`${origin}/health`, { cache: "no-store" });
      const body = await response.json();
      if (response.ok && body.status === "ok" && body.name === "shell-mcp") return body;
    } catch {}
    await sleep(25);
  }
  throw new Error("real-state off-path front door did not become healthy");
}

function requestLogEntries() {
  return readFileSync(requestLogPath, "utf8").trim().split(/\r?\n/).filter(Boolean).map((line) => JSON.parse(line));
}

function establishedBackendLocalPorts(frontDoorPid, backendPort) {
  const command = `@(Get-NetTCPConnection -State Established -OwningProcess ${frontDoorPid} -RemotePort ${backendPort} -ErrorAction SilentlyContinue | Select-Object -ExpandProperty LocalPort | Sort-Object -Unique) -join ","`;
  const text = execFileSync("powershell.exe", ["-NoProfile", "-NonInteractive", "-Command", command], { encoding: "utf8" }).trim();
  return text ? text.split(",").map((value) => Number(value)).filter(Number.isInteger) : [];
}

try {
  copyFileSync(join(sourceState, "active-backend.json"), configPath);
  copyFileSync(join(sourceState, "process-routes.json"), processRoutesPath);
  copyFileSync(join(sourceState, "static-routes.json"), staticRoutesPath);
  const copiedRoutes = JSON.parse(readFileSync(staticRoutesPath, "utf8"));
  assert.deepEqual(copiedRoutes.routes["clone-a"], [3041]);
  assert.deepEqual(copiedRoutes.routes["clone-b"], [3022, 3012]);

  const port = await unusedPort();
  frontDoor = spawn(process.execPath, [join(root, "dist", "front-door.js")], {
    cwd: root,
    env: {
      ...process.env,
      FRONT_DOOR_PORT: String(port),
      MCP_BACKEND_CONFIG_PATH: configPath,
      MCP_PROCESS_ROUTE_PATH: processRoutesPath,
      FRONT_DOOR_STATIC_ROUTE_PATH: staticRoutesPath,
      FRONT_DOOR_REQUEST_LOG_PATH: requestLogPath,
    },
    stdio: ["ignore", "pipe", "pipe"],
    windowsHide: true,
  });
  let stderr = "";
  frontDoor.stderr.on("data", (chunk) => { stderr += chunk.toString(); });
  const origin = `http://127.0.0.1:${port}`;
  const health = await waitHealth(origin);
  assert.equal(health.port, port);

  const cloneBHealth = await fetch(`${origin}/clone-b/health`, { cache: "no-store" });
  await cloneBHealth.text();
  assert.ok([200, 503].includes(cloneBHealth.status), `unexpected clone-b health status ${cloneBHealth.status}`);

  const cloneAProbe = await fetch(`${origin}/clone-a/mcp`, { headers: { accept: "application/json, text/event-stream" } });
  await cloneAProbe.text();

  const connectionSnapshots = [];
  for (let index = 0; index < 10; index += 1) {
    const response = await fetch(`${origin}/clone-a/mcp`, { headers: { accept: "application/json, text/event-stream" } });
    await response.text();
    await sleep(20);
    connectionSnapshots.push(establishedBackendLocalPorts(health.pid, 3041));
  }
  const actualBackendConnections = new Set(connectionSnapshots.flat());
  assert.ok(actualBackendConnections.size > 0, `no persistent 3041 backend connection observed; stderr=${stderr}`);
  assert.ok(actualBackendConnections.size <= 2, `static proxy opened too many persistent 3041 connections: ${[...actualBackendConnections].join(",")}`);

  const entries = requestLogEntries();
  const cloneADispatches = entries.filter((entry) => entry.event === "front_static_dispatch" && entry.route === "clone-a");
  assert.ok(cloneADispatches.length >= 11, `expected clone-a dispatch evidence, got ${cloneADispatches.length}`);
  assert.ok(cloneADispatches.every((entry) => entry.backend_port === 3041), "clone-a dispatched to a port other than 3041");
  const cloneBRetryOrDispatch = entries.filter((entry) => entry.route === "clone-b" && ["front_static_dispatch", "front_static_unhealthy", "front_static_retry"].includes(entry.event));

  console.log(JSON.stringify({
    result: "PASS",
    offpath_port: port,
    front_door_pid: health.pid,
    health: true,
    copied_route_map: { "clone-a": [3041], "clone-b": [3022, 3012] },
    clone_b_array_parsed: true,
    clone_b_health_status: cloneBHealth.status,
    clone_a_dispatches_to_3041: cloneADispatches.length,
    persistent_3041_backend_connections: actualBackendConnections.size,
    clone_b_route_evidence: cloneBRetryOrDispatch.length,
  }));
} finally {
  if (frontDoor && frontDoor.exitCode === null) frontDoor.kill();
  await sleep(150);
  rmSync(temporary, { recursive: true, force: true });
}

