 71: function staticRouteForUrl(rawUrl: string, requestPath: string): { route: StaticRoute; upstreamPath: string } | undefined {
 72:   const queryIndex = rawUrl.indexOf("?");
 73:   const query = queryIndex >= 0 ? rawUrl.slice(queryIndex) : "";
 74:   for (const route of staticRoutes()) {
 75:     const prefix = `/${route.slug}`;
 76:     if (requestPath === prefix || requestPath.startsWith(`${prefix}/`)) {
 77:       const stripped = requestPath.slice(prefix.length) || "/";
 78:       return { route, upstreamPath: `${stripped}${query}` };
 79:     }
 80:     for (const base of ["/.well-known/oauth-authorization-server/", "/.well-known/oauth-protected-resource/", "/.well-known/openid-configuration/"]) {
 81:       const marker = `${base}${route.slug}`;
 82:       if (requestPath === marker || requestPath.startsWith(`${marker}/`)) return { route, upstreamPath: rawUrl };
 83:     }
 84:   }
 85:   return undefined;
 86: }
