 88: let lastBackend: BackendTarget | undefined;
 89: function backendTarget(): BackendTarget {
 90:   try {
 91:     const parsed = JSON.parse(readFileSync(BACKEND_CONFIG_PATH, "utf8").replace(/^\uFEFF/, "")) as unknown;
 92:     if (!validBackend(parsed)) throw new Error("invalid backend config");
 93:     lastBackend = parsed;
 94:   } catch (error) {
 95:     if (!lastBackend) throw error;
 96:   }
 97:   return lastBackend!;
 98: }
