100: function loadProcessRoutes(): Map<string, ProcessRoute> {
101:   try {
102:     const parsed = JSON.parse(readFileSync(PROCESS_ROUTES_PATH, "utf8").replace(/^\uFEFF/, "")) as Partial<ProcessRouteFile>;
103:     if (parsed.version !== 1 || !parsed.routes || typeof parsed.routes !== "object") return new Map();
104:     return new Map(Object.entries(parsed.routes).filter(([id, route]) => PROCESS_ID_PATTERN.test(id) && validRoute(route)));
105:   } catch {
106:     return new Map();
107:   }
108: }
109: 
110: function validRoute(value: unknown): value is ProcessRoute {
111:   if (!value || typeof value !== "object") return false;
112:   const route = value as Partial<ProcessRoute>;
113:   return Number.isInteger(route.port) && route.port! >= 1024 && route.port! <= 65535 && typeof route.generation === "string" && typeof route.created_at === "string";
114: }
