116: const processRoutes = loadProcessRoutes();
117: function persistProcessRoutes(): void {
118:   mkdirSync(dirname(PROCESS_ROUTES_PATH), { recursive: true });
119:   const temporary = `${PROCESS_ROUTES_PATH}.${process.pid}.tmp`;
120:   const routes = Object.fromEntries([...processRoutes.entries()].sort(([left], [right]) => left.localeCompare(right)));
121:   writeFileSync(temporary, `${JSON.stringify({ version: 1, routes }, null, 2)}\n`, "utf8");
122:   renameSync(temporary, PROCESS_ROUTES_PATH);
123: }
