125: function parseMcpCall(body: Buffer): McpCall {
126:   try {
127:     const request = JSON.parse(body.toString("utf8")) as { method?: unknown; params?: { name?: unknown; arguments?: Record<string, unknown> } };
128:     if (request.method !== "tools/call" || typeof request.params?.name !== "string") return {};
129:     const tool = request.params.name;
130:     const args = request.params.arguments || {};
131:     let processId = typeof args.process_id === "string" ? args.process_id : undefined;
132:     if (!processId && typeof args.scope === "string" && args.scope.startsWith("process:")) processId = args.scope.slice("process:".length);
133:     return { tool, processId };
134:   } catch {
135:     return {};
136:   }
137: }
138: 
139: function rpcBody(body: Buffer, contentType: string): unknown {
140:   const text = body.toString("utf8");
141:   try {
142:     if (contentType.includes("text/event-stream")) {
143:       const matches = [...text.matchAll(/^data:\s*(.+)$/gm)];
144:       return matches.length ? JSON.parse(matches.at(-1)![1]) : undefined;
145:     }
146:     return JSON.parse(text);
147:   } catch {
148:     return undefined;
149:   }
150: }
151: 
152: function toolPayload(body: Buffer, contentType: string): Record<string, unknown> | undefined {
153:   const rpc = rpcBody(body, contentType) as { result?: { content?: Array<{ type?: string; text?: string }> } } | undefined;
154:   const text = rpc?.result?.content?.find((item) => item.type === "text" && typeof item.text === "string")?.text;
155:   if (!text) return undefined;
156:   try {
157:     const value = JSON.parse(text) as unknown;
158:     return value && typeof value === "object" ? value as Record<string, unknown> : undefined;
159:   } catch {
160:     return undefined;
161:   }
162: }
163: 
164: function updateProcessRoute(call: McpCall, target: BackendTarget, responseBody: Buffer, contentType: string): void {
165:   const result = toolPayload(responseBody, contentType);
166:   if (!result) return;
167:   if (call.tool === "start_process" && typeof result.process_id === "string" && PROCESS_ID_PATTERN.test(result.process_id)) {
168:     processRoutes.set(result.process_id, { port: target.port, generation: target.generation, created_at: new Date().toISOString() });
169:     persistProcessRoutes();
170:     return;
171:   }
172:   if (!call.processId || !processRoutes.has(call.processId)) return;
173:   if ((call.tool === "read_output" && result.running === false) || (call.tool === "kill_process" && (result.killed === true || result.already_exited === true))) {
174:     processRoutes.delete(call.processId);
175:     persistProcessRoutes();
176:   }
177: }
