179: function outgoingHeaders(headers: IncomingHttpHeaders, target: { port: number }): IncomingHttpHeaders {
180:   const next: IncomingHttpHeaders = {};
181:   for (const [name, value] of Object.entries(headers)) {
182:     if (!HOP_BY_HOP_HEADERS.has(name.toLowerCase())) next[name] = value;
183:   }
184:   // Preserve the original Host and forwarded headers. The backend explicitly
185:   // allowlists the front-door host, and worker-visible request semantics stay exact.
186:   if (!next.host) next.host = `127.0.0.1:${target.port}`;
187:   return next;
188: }
189: 
190: function copyResponseHeaders(headers: IncomingHttpHeaders, response: ServerResponse): void {
191:   for (const [name, value] of Object.entries(headers)) {
192:     if (value !== undefined && !HOP_BY_HOP_HEADERS.has(name.toLowerCase())) response.setHeader(name, value);
193:   }
194: }
