196: let activeRequests = 0;
197: let totalRequests = 0;
198: 
199: async function targetGenerationMatches(target: BackendTarget): Promise<boolean> {
200:   return new Promise((resolveMatch) => {
201:     const probe = httpRequest({ host: "127.0.0.1", port: target.port, path: "/health", method: "GET", agent: false }, (probeResponse) => {
202:       const chunks: Buffer[] = [];
203:       probeResponse.on("data", (chunk: Buffer) => chunks.push(chunk));
204:       probeResponse.on("end", () => {
205:         try {
206:           const health = JSON.parse(Buffer.concat(chunks).toString("utf8")) as { status?: unknown; name?: unknown; pid?: unknown; backend_generation?: unknown };
207:           if (health.status !== "ok" || health.name !== "shell-mcp") return resolveMatch(false);
208:           if (target.generation.startsWith("legacy-")) return resolveMatch(String(health.pid) === target.generation.slice("legacy-".length));
209:           resolveMatch(health.backend_generation === target.generation);
210:         } catch { resolveMatch(false); }
211:       });
212:     });
213:     probe.setTimeout(1_000, () => probe.destroy());
214:     probe.on("error", () => resolveMatch(false));
215:     probe.end();
216:   });
217: }
