219: async function proxyRequest(request: IncomingMessage, response: ServerResponse, body: Buffer, call: McpCall, requestId?: string): Promise<void> {
220:   const active = backendTarget();
221:   const pinned = call.processId ? processRoutes.get(call.processId) : undefined;
222:   const target = pinned ? { version: 1 as const, port: pinned.port, generation: pinned.generation } : active;
223:   if (requestId) frontDoorLog("front_backend_select", { request_id: requestId, tool: call.tool || null, process_id: call.processId || null, backend_port: target.port, backend_generation: target.generation, pinned: Boolean(pinned) });
224:   if (!await targetGenerationMatches(target)) {
225:     if (requestId) frontDoorLog("front_backend_unavailable", { request_id: requestId, backend_port: target.port, backend_generation: target.generation });
226:     if (!response.destroyed && !response.headersSent) {
227:       response.statusCode = 503;
228:       response.setHeader("content-type", "application/json");
229:       response.setHeader("retry-after", "1");
230:       response.end(JSON.stringify({ error: "Service unavailable" }));
231:     }
232:     return;
233:   }
234:   activeRequests += 1;
235:   totalRequests += 1;
236:   let settled = false;
237:   const finish = () => {
238:     if (settled) return;
239:     settled = true;
240:     activeRequests -= 1;
241:   };
242:   if (requestId) frontDoorLog("front_backend_dispatch", { request_id: requestId, backend_port: target.port, backend_generation: target.generation });
243:   const upstream = httpRequest({
244:     host: "127.0.0.1",
245:     port: target.port,
246:     method: request.method,
247:     path: request.url,
248:     headers: outgoingHeaders(request.headers, target),
249:     agent: backendAgent,
250:   }, (backendResponse) => {
251:     if (requestId) frontDoorLog("front_backend_response", { request_id: requestId, backend_port: target.port, status: backendResponse.statusCode || null });
252:     if (!response.destroyed && !response.headersSent) {
253:       response.statusCode = backendResponse.statusCode || 502;
254:       response.statusMessage = backendResponse.statusMessage || response.statusMessage;
255:       copyResponseHeaders(backendResponse.headers, response);
256:     }
257:     const captured: Buffer[] = [];
258:     let capturedBytes = 0;
259:     backendResponse.on("data", (chunk: Buffer) => {
260:       if (capturedBytes < MAX_CAPTURE_BYTES) {
261:         const remaining = MAX_CAPTURE_BYTES - capturedBytes;
262:         captured.push(chunk.subarray(0, remaining));
263:         capturedBytes += Math.min(chunk.length, remaining);
264:       }
265:       if (!response.destroyed) response.write(chunk);
266:     });
267:     backendResponse.on("end", () => {
268:       const responseBody = Buffer.concat(captured);
269:       updateProcessRoute(call, target, responseBody, String(backendResponse.headers["content-type"] || ""));
270:       if (!response.destroyed) response.end();
271:       finish();
272:     });
273:     backendResponse.on("error", () => {
274:       if (!response.destroyed) response.destroy();
275:       finish();
276:     });
277:   });
278:   upstream.setTimeout(35_000, () => upstream.destroy(new Error("backend request timeout")));
279:   upstream.on("error", (error) => {
280:     if (requestId) frontDoorLog("front_backend_error", { request_id: requestId, backend_port: target.port, error: error.message });
281:     if (!response.destroyed && !response.headersSent) {
282:       response.statusCode = 503;
283:       response.setHeader("content-type", "application/json");
284:       response.setHeader("retry-after", "1");
285:       response.end(JSON.stringify({ error: "Service unavailable" }));
286:     } else if (!response.destroyed) {
287:       response.destroy();
288:     }
289:     finish();
290:   });
291:   upstream.end(body);
292: }
293: 
294: function staticAttempt(request: IncomingMessage, body: Buffer, match: { route: StaticRoute; upstreamPath: string }, port: number): Promise<StaticAttempt> {
295:   return new Promise((resolveAttempt, rejectAttempt) => {
296:     let settled = false;
297:     const fail = (error: Error) => {
298:       if (settled) return;
299:       settled = true;
300:       rejectAttempt(error);
301:     };
302:     const upstream = httpRequest({
303:       host: "127.0.0.1",
304:       port,
305:       method: request.method,
306:       path: match.upstreamPath,
307:       headers: outgoingHeaders(request.headers, { port }),
308:       agent: backendAgent,
309:     }, (backendResponse) => {
310:       const chunks: Buffer[] = [];
311:       let capturedBytes = 0;
312:       backendResponse.on("data", (chunk: Buffer) => {
313:         capturedBytes += chunk.length;
314:         if (capturedBytes > MAX_CAPTURE_BYTES) {
315:           backendResponse.destroy(new Error("static backend response exceeded capture limit"));
316:           return;
317:         }
318:         chunks.push(chunk);
319:       });
320:       backendResponse.on("end", () => {
321:         if (settled) return;
322:         settled = true;
323:         resolveAttempt({
324:           port,
325:           statusCode: backendResponse.statusCode || 502,
326:           statusMessage: backendResponse.statusMessage,
327:           headers: backendResponse.headers,
328:           body: Buffer.concat(chunks),
329:         });
330:       });
331:       backendResponse.on("error", fail);
332:     });
333:     // A normal start_process request may intentionally wait for output before
334:     // returning. Match the dynamic proxy's bound so a successful command is
335:     // not reported as 503 merely because wait_ms exceeds the health-probe
336:     // timeout. Ambiguous timeouts are still never retried.
337:     upstream.setTimeout(35_000, () => upstream.destroy(new Error("static backend request timeout")));
338:     upstream.on("error", fail);
339:     upstream.end(body);
340:   });
341: }
342: 
343: function staticBackendHealthy(port: number): Promise<boolean> {
344:   return new Promise((resolveHealthy) => {
345:     let settled = false;
346:     const finish = (healthy: boolean) => {
347:       if (settled) return;
348:       settled = true;
349:       resolveHealthy(healthy);
350:     };
351:     const probe = httpRequest({ host: "127.0.0.1", port, path: "/health", method: "GET", agent: false }, (probeResponse) => {
352:       const chunks: Buffer[] = [];
353:       probeResponse.on("data", (chunk: Buffer) => chunks.push(chunk));
354:       probeResponse.on("end", () => {
355:         try {
356:           const health = JSON.parse(Buffer.concat(chunks).toString("utf8")) as { status?: unknown; name?: unknown; port?: unknown };
357:           finish(probeResponse.statusCode === 200 && health.status === "ok" && health.name === "shell-mcp" && health.port === port);
358:         } catch { finish(false); }
359:       });
360:     });
361:     probe.setTimeout(1_000, () => probe.destroy(new Error("static backend health timeout")));
362:     probe.on("error", () => finish(false));
363:     probe.end();
364:   });
365: }
