367: function retryableStaticStatus(statusCode: number): boolean {
368:   // These responses prove the replacement rejected the request before a tool
369:   // ran. Retrying an ambiguous timeout or 5xx could execute start_process twice.
370:   return statusCode === 401 || statusCode === 403 || statusCode === 404;
371: }
372: 
373: async function proxyStaticRequest(request: IncomingMessage, response: ServerResponse, body: Buffer, match: { route: StaticRoute; upstreamPath: string }, requestId?: string): Promise<void> {
374:   activeRequests += 1;
375:   totalRequests += 1;
376:   let lastAttempt: StaticAttempt | undefined;
377:   try {
378:     for (let index = 0; index < match.route.ports.length; index += 1) {
379:       const port = match.route.ports[index];
380:       if (!await staticBackendHealthy(port)) {
381:         if (requestId) frontDoorLog("front_static_unhealthy", { request_id: requestId, route: match.route.slug, backend_port: port, fallback_index: index });
382:         if (index === match.route.ports.length - 1) throw new Error("all static backends are unhealthy");
383:         if (requestId) frontDoorLog("front_static_retry", { request_id: requestId, route: match.route.slug, failed_backend_port: port, status: null, next_backend_port: match.route.ports[index + 1] });
384:         continue;
385:       }
386:       if (requestId) frontDoorLog("front_static_dispatch", { request_id: requestId, route: match.route.slug, backend_port: port, upstream_path: match.upstreamPath.split("?", 1)[0], fallback_index: index });
387:       try {
388:         const attempt = await staticAttempt(request, body, match, port);
389:         lastAttempt = attempt;
390:         if (requestId) frontDoorLog("front_static_response", { request_id: requestId, route: match.route.slug, backend_port: port, status: attempt.statusCode, fallback_index: index });
391:         if (!retryableStaticStatus(attempt.statusCode) || index === match.route.ports.length - 1) break;
392:         if (requestId) frontDoorLog("front_static_retry", { request_id: requestId, route: match.route.slug, failed_backend_port: port, status: attempt.statusCode, next_backend_port: match.route.ports[index + 1] });
393:       } catch (error) {
394:         if (requestId) frontDoorLog("front_static_error", { request_id: requestId, route: match.route.slug, backend_port: port, error: error instanceof Error ? error.message : String(error), fallback_index: index });
395:         throw error;
396:       }
397:     }
398:     if (!lastAttempt) throw new Error("no static backend returned a response");
399:     if (!response.destroyed && !response.headersSent) {
400:       response.statusCode = lastAttempt.statusCode;
401:       response.statusMessage = lastAttempt.statusMessage || response.statusMessage;
402:       copyResponseHeaders(lastAttempt.headers, response);
403:       response.end(lastAttempt.body);
404:     }
405:   } catch {
406:     if (!response.destroyed && !response.headersSent) {
407:       response.statusCode = 503;
408:       response.setHeader("content-type", "application/json");
409:       response.setHeader("retry-after", "1");
410:       response.end(JSON.stringify({ error: "Service unavailable" }));
411:     } else if (!response.destroyed) response.destroy();
412:   } finally {
413:     activeRequests -= 1;
414:   }
415: }
