417: async function readBody(request: IncomingMessage): Promise<Buffer> {
418:   const chunks: Buffer[] = [];
419:   let size = 0;
420:   for await (const raw of request) {
421:     const chunk = Buffer.isBuffer(raw) ? raw : Buffer.from(raw);
422:     size += chunk.length;
423:     if (size > MAX_REQUEST_BYTES) throw new Error("request_too_large");
424:     chunks.push(chunk);
425:   }
426:   return Buffer.concat(chunks);
427: }
