429: const server = createServer(async (request, response) => {
430:   const rawUrl = request.url || "";
431:   const requestPath = rawUrl.split("?", 1)[0] || "";
432:   const staticMatch = staticRouteForUrl(rawUrl, requestPath);
433:   const isMcpRequest = requestPath === "/mcp" || staticMatch?.upstreamPath.split("?", 1)[0] === "/mcp";
434:   const requestId = isMcpRequest ? `${process.pid}-${Date.now()}-${++requestSequence}` : undefined;
435:   const requestStartedAt = Date.now();
436:   let requestFinished = false;
437:   if (requestId) {
438:     frontDoorLog("front_request_start", { request_id: requestId, method: request.method || null, path: requestPath });
439:     request.once("aborted", () => frontDoorLog("front_request_aborted", { request_id: requestId }));
440:     response.once("finish", () => {
441:       requestFinished = true;
442:       frontDoorLog("front_request_finish", { request_id: requestId, status: response.statusCode, duration_ms: Date.now() - requestStartedAt });
443:     });
444:     response.once("close", () => {
445:       if (!requestFinished) frontDoorLog("front_request_close", { request_id: requestId, status: response.statusCode, duration_ms: Date.now() - requestStartedAt, writable_ended: response.writableEnded });
446:     });
447:   }
448:   if (request.method === "GET" && requestPath === "/health") {
449:     response.statusCode = 200;
450:     response.setHeader("content-type", "application/json");
451:     response.setHeader("cache-control", "no-store");
452:     response.end(JSON.stringify({ status: "ok", name: "shell-mcp", host: HOST, port: PORT, pid: process.pid, active_requests: activeRequests, total_requests: totalRequests }));
453:     return;
454:   }
455:   try {
456:     const body = await readBody(request);
457:     const call = isMcpRequest ? parseMcpCall(body) : {};
458:     if (requestId) frontDoorLog("front_request_parsed", { request_id: requestId, tool: call.tool || null, process_id: call.processId || null, static_route: staticMatch?.route.slug || null });
459:     if (staticMatch) await proxyStaticRequest(request, response, body, staticMatch, requestId);
460:     else await proxyRequest(request, response, body, call, requestId);
461:   } catch (error) {
462:     if (!response.headersSent) {
463:       response.statusCode = error instanceof Error && error.message === "request_too_large" ? 413 : 500;
464:       response.setHeader("content-type", "application/json");
465:       response.end(JSON.stringify({ error: error instanceof Error ? error.message : String(error) }));
466:     }
467:   }
468: });
