470: server.on("clientError", (error, socket) => {
471:   frontDoorLog("front_client_error", { code: "code" in error ? error.code : null, error: error.message });
472:   // Installing a clientError listener disables Node's default malformed-socket
473:   // cleanup. Always close the socket here so a Funnel-side reset or parse error
474:   // cannot leave a dead public connection retained by the stable front door.
475:   if (socket.writable && !("code" in error && error.code === "ECONNRESET")) {
476:     socket.end("HTTP/1.1 400 Bad Request\r\nConnection: close\r\nContent-Length: 0\r\n\r\n", () => socket.destroy());
477:   } else {
478:     socket.destroy();
479:   }
