490: const stop = () => {
491:   server.close(() => { backendAgent.destroy(); requestLogStream.end(() => process.exit(0)); });
492:   setTimeout(() => process.exit(1), 5_000).unref();
493: };
494: process.on("SIGINT", stop);
495: process.on("SIGTERM", stop);

  1: param(
  2:     [ValidateSet('All','FrontDoor','Backend','Legacy')][string]$Role = 'All',
  3:     [int]$Port = 0,
  4:     [int]$PollSeconds = 15,
  5:     [string]$BackendConfigPath = '',
  6:     [string]$ProcessRoutePath = '',
  7:     [string]$SupervisorStateRoot = '',
  8:     [switch]$TestMode
  9: )
 10: $ErrorActionPreference = 'Stop'
 11: $Root = Split-Path -Parent $MyInvocation.MyCommand.Path
 12: Set-Location $Root
 13: if ($PollSeconds -lt 5) { throw 'PollSeconds must be >= 5' }
 14: if ($Role -eq 'All') {
 15:     $allMutex = New-Object System.Threading.Mutex($false,'Global\CodexLocalMcpKeepAlive-All')
 16:     $allHeld = $false
 17:     try {
 18:         try { $allHeld = $allMutex.WaitOne(0) } catch [System.Threading.AbandonedMutexException] { $allHeld = $true }
 19:         if (-not $allHeld) { exit 0 }
 20:         $definitions = @(
 21:             @{ Role='FrontDoor'; Port=3003 },
 22:             @{ Role='Backend'; Port=3001 },
 23:             @{ Role='Backend'; Port=3002 }
 24:         )
 25:         while ($true) {
 26:             foreach ($definition in $definitions) {
 27:                 $rolePattern = '-Role\s+' + [regex]::Escape($definition.Role) + '(\s|$)'
 28:                 $portPattern = '-Port\s+' + [regex]::Escape([string]$definition.Port) + '(\s|$)'
 29:                 $supervisor = Get-CimInstance Win32_Process -ErrorAction SilentlyContinue | Where-Object {
 30:                     $_.Name -eq 'powershell.exe' -and $_.CommandLine -match 'ChatGPTMcpClean\\keepalive\.ps1' -and $_.CommandLine -match $rolePattern -and $_.CommandLine -match $portPattern
 31:                 } | Select-Object -First 1
 32:                 if (-not $supervisor) {
 33:                     Start-Process powershell.exe -ArgumentList @('-NoProfile','-NonInteractive','-ExecutionPolicy','Bypass','-File',(Join-Path $Root 'keepalive.ps1'),'-Role',$definition.Role,'-Port',[string]$definition.Port,'-PollSeconds',[string]$PollSeconds) -WorkingDirectory $Root -WindowStyle Hidden | Out-Null
 34:                 }
 35:             }
 36:             Start-Sleep -Seconds $PollSeconds
 37:         }
 38:     } finally {
 39:         if ($allHeld) { $allMutex.ReleaseMutex() }
 40:         $allMutex.Dispose()
 41:     }
 42:     exit 0
 43: }
