 69:   deadline_at: string;
 70:   max_chars?: number;
 71:   wait_ms?: number;
 72: };
 73: 
 74: type ProcessControlResponse = {
 75:   version: 1;
 76:   request_id: string;
 77:   process_id: string;
 78:   responded_at: string;
 79:   result?: Record<string, unknown>;
 80:   error?: string;
 81: };
 82: 
 83: const PROCESS_ID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
 84: 
 85: class BoundedCapture {
 86:   private readonly chunks: string[] = [];
 87:   private length = 0;
 88:   truncated = false;
 89: 
 90:   append(chunk: Buffer | string): void {
 91:     let text = chunk.toString();
 92:     if (!text) return;
 93:     if (text.length >= MAX_CAPTURE_CHARS) {
 94:       text = text.slice(-MAX_CAPTURE_CHARS);
 95:       this.chunks.length = 0;
 96:       this.chunks.push(text);
 97:       this.length = text.length;
 98:       this.truncated = true;
 99:       return;
100:     }
101:     this.chunks.push(text);
102:     this.length += text.length;
103:     while (this.length > MAX_CAPTURE_CHARS) {
104:       const overflow = this.length - MAX_CAPTURE_CHARS;
105:       const first = this.chunks[0]!;
106:       if (first.length <= overflow) {
107:         this.chunks.shift();
108:         this.length -= first.length;
109:       } else {
110:         this.chunks[0] = first.slice(overflow);
111:         this.length -= overflow;
112:       }
113:       this.truncated = true;
114:     }
115:   }
116: 
117:   // ceiling defaults to the transport cap. Receipts pass MAX_CAPTURE_CHARS because they
118:   // are written to disk, never sent over MCP, and are the only durable proof of what a
119:   // process produced when the caller's read is blocked or truncated.
120:   tail(maxChars: number, ceiling: number = MAX_READ_CHARS): { text: string; truncated: boolean; dropped: number } {
121:     let remaining = Math.max(1, Math.min(maxChars, ceiling));
122:     const parts: string[] = [];
123:     for (let index = this.chunks.length - 1; index >= 0 && remaining > 0; index -= 1) {
124:       const chunk = this.chunks[index]!;
125:       const part = chunk.length <= remaining ? chunk : chunk.slice(-remaining);
126:       parts.push(part);
127:       remaining -= part.length;
128:     }
129:     const text = parts.reverse().join("");
130:     // dropped counts the characters cut from the START, because this returns the tail.
131:     // A caller that asked for the first N lines of a file gets the last slice of that
132:     // output, so a bare boolean is not enough to notice the beginning is missing.
133:     const dropped = Math.max(0, this.length - text.length);
134:     return { text, truncated: this.truncated || this.length > maxChars, dropped };
135:   }
136: }
