138: type ProcessState = {
139:   id: string;
140:   pid: number;
141:   callerId: string;
142:   ownerContext: TelemetryContext;
143:   command: string;
144:   cwd: string;
145:   child: CapturedChild;
146:   stdout: BoundedCapture;
147:   stderr: BoundedCapture;
148:   startedAt: string;
149:   finishedAt?: string;
150:   exitCode: number | null;
151:   signal?: NodeJS.Signals | null;
152:   error?: string;
153:   done: Promise<void>;
154:   revision: number;
155:   lastReadRevisionByCaller: Map<string, number>;
