159: // Absolute path so a mangled PATH in an inherited environment cannot turn into a
160: // spawn failure. Falls back to bare resolution only if SystemRoot is unset.
161: const POWERSHELL_EXE = process.env.SystemRoot
162:   ? `${process.env.SystemRoot}\\System32\\WindowsPowerShell\\v1.0\\powershell.exe`
163:   : "powershell.exe";
164: 
165: // spawn() reports ENOENT when the *cwd* does not exist, and node attributes it to the
166: // executable -- "spawn powershell.exe ENOENT" for a bad working_directory sends callers
167: // hunting a PATH problem that does not exist. Validate the directory up front and fail
168: // with a message that names the real cause.
169: function normalizedCwd(workingDirectory?: string): string {
170:   if (!workingDirectory) return process.cwd();
171:   if (!isAbsolute(workingDirectory)) {
172:     throw new Error(`working_directory must be an absolute path, received "${workingDirectory}"`);
173:   }
174:   const resolved = resolve(workingDirectory);
175:   let stats;
176:   try {
177:     stats = statSync(resolved);
178:   } catch {
179:     throw new Error(`working_directory does not exist: "${resolved}"`);
180:   }
181:   if (!stats.isDirectory()) {
182:     throw new Error(`working_directory is not a directory: "${resolved}"`);
183:   }
184:   return resolved;
185: }
186: 
187: function powershell(command: string, cwd: string): CapturedChild {
188:   return spawn(
189:     POWERSHELL_EXE,
190:     ["-NoLogo", "-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass", "-Command", command],
191:     {
192:       cwd,
193:       windowsHide: true,
194:       stdio: ["ignore", "pipe", "pipe"],
195:       env: process.env,
196:     },
197:   );
198: }
