200: async function taskkillTree(pid: number): Promise<{ code: number; timedOut: boolean }> {
201:   return await new Promise<{ code: number; timedOut: boolean }>((resolve, reject) => {
202:     const killer = spawn("taskkill.exe", ["/PID", String(pid), "/T", "/F"], {
203:       windowsHide: true,
204:       stdio: "ignore",
205:     });
206:     let settled = false;
207:     const finish = (result: { code: number; timedOut: boolean }) => {
208:       if (settled) return;
209:       settled = true;
210:       clearTimeout(timer);
211:       resolve(result);
212:     };
213:     const timer = setTimeout(() => {
214:       killer.kill();
215:       finish({ code: 124, timedOut: true });
216:     }, TASKKILL_TIMEOUT_MS);
217:     killer.once("error", (error) => {
218:       if (settled) return;
219:       settled = true;
220:       clearTimeout(timer);
221:       reject(error);
222:     });
223:     killer.once("close", (code) => finish({ code: code ?? 1, timedOut: false }));
224:   });
225: }
