231: function processResponseState(startedAt: string, running: boolean, finishedAt?: string | null): {
232:   mcp_status: "OK";
233:   process_state: "RUNNING" | "COMPLETED";
234:   elapsed_ms: number;
235:   next_action: "READ_SAME_PROCESS_ID" | "STOP_READING";
236: } {
237:   const endMs = running ? Date.now() : Date.parse(finishedAt ?? startedAt);
238:   return {
239:     mcp_status: "OK",
240:     process_state: running ? "RUNNING" : "COMPLETED",
241:     elapsed_ms: Math.max(0, endMs - Date.parse(startedAt)),
242:     next_action: running ? "READ_SAME_PROCESS_ID" : "STOP_READING",
243:   };
244: }
