246: export class ProcessManager {
247:   private readonly processes = new Map<string, ProcessState>();
248:   private readonly launchBucketsByCaller = new Map<string, LaunchBucket>();
249:   private readonly launchBucketCapacity: number;
250:   private readonly launchRefillMs: number;
251:   private readonly maxLivePerCaller: number;
252:   private readonly now: () => number;
253:   private readonly receiptDirectory?: string;
254:   private readonly controlRequestDirectory?: string;
255:   private readonly controlResponseDirectory?: string;
256:   private readonly controlRequestsInFlight = new Set<string>();
257:   private lastControlPruneAt = 0;
258: 
259:   constructor(options: ProcessManagerOptions = {}) {
260:     this.launchBucketCapacity = options.maxLaunchesPerWindow ?? DEFAULT_LAUNCH_BUCKET_CAPACITY;
261:     this.launchRefillMs = options.launchRefillMs ?? DEFAULT_LAUNCH_REFILL_MS;
262:     this.maxLivePerCaller = options.maxLivePerCaller ?? DEFAULT_MAX_LIVE_PER_CALLER;
263:     this.now = options.now ?? Date.now;
264:     this.receiptDirectory = options.receiptDirectory ? resolve(options.receiptDirectory) : undefined;
265:     if (this.receiptDirectory) {
266:       mkdirSync(this.receiptDirectory, { recursive: true });
267:       this.controlRequestDirectory = join(this.receiptDirectory, ".control", "requests");
268:       this.controlResponseDirectory = join(this.receiptDirectory, ".control", "responses");
269:       mkdirSync(this.controlRequestDirectory, { recursive: true });
270:       mkdirSync(this.controlResponseDirectory, { recursive: true });
271:       this.pruneReceipts();
272:       this.pruneControlFiles();
273:       const controlTimer = setInterval(() => this.sweepControlRequests(), CONTROL_POLL_MS);
274:       controlTimer.unref();
275:     }
276:   }
277: 
278:   private receiptPath(processId: string): string | undefined {
279:     if (!this.receiptDirectory || !PROCESS_ID_PATTERN.test(processId)) return undefined;
280:     return join(this.receiptDirectory, `${processId}.json`);
281:   }
282: 
283:   private pruneReceipts(): void {
284:     if (!this.receiptDirectory) return;
285:     const now = Date.now();
286:     const files = readdirSync(this.receiptDirectory, { withFileTypes: true })
287:       .filter((entry) => entry.isFile() && PROCESS_ID_PATTERN.test(entry.name.slice(0, -5)) && entry.name.endsWith(".json"))
288:       .map((entry) => {
289:         const path = join(this.receiptDirectory!, entry.name);
290:         return { path, modifiedAt: statSync(path).mtimeMs };
291:       })
292:       .sort((a, b) => a.modifiedAt - b.modifiedAt);
293:     for (const file of files) {
294:       if (now - file.modifiedAt > COMPLETED_RETENTION_MS) unlinkSync(file.path);
295:     }
296:   }
297: 
298:   private controlPath(directory: string | undefined, requestId: string): string | undefined {
299:     if (!directory || !PROCESS_ID_PATTERN.test(requestId)) return undefined;
300:     return join(directory, `${requestId}.json`);
301:   }
302: 
303:   private writeControlFile(path: string, value: ProcessControlRequest | ProcessControlResponse): void {
304:     const temporaryPath = `${path}.${process.pid}.${randomUUID()}.tmp`;
305:     try {
306:       writeFileSync(temporaryPath, JSON.stringify(value), { encoding: "utf8", flag: "wx" });
307:       renameSync(temporaryPath, path);
308:     } finally {
309:       try { unlinkSync(temporaryPath); } catch { /* already renamed or never created */ }
310:     }
311:   }
312: 
313:   private pruneControlFiles(): void {
314:     const now = Date.now();
315:     if (now - this.lastControlPruneAt < CONTROL_PRUNE_INTERVAL_MS) return;
316:     this.lastControlPruneAt = now;
317:     const cutoff = now - CONTROL_RETENTION_MS;
318:     for (const directory of [this.controlRequestDirectory, this.controlResponseDirectory]) {
319:       if (!directory) continue;
320:       let entries;
321:       try {
322:         entries = readdirSync(directory, { withFileTypes: true });
323:       } catch {
324:         continue;
325:       }
326:       for (const entry of entries) {
327:         if (!entry.isFile() || !entry.name.endsWith(".json")) continue;
328:         const path = join(directory, entry.name);
329:         try {
330:           if (statSync(path).mtimeMs < cutoff) unlinkSync(path);
331:         } catch { /* best-effort cleanup */ }
332:       }
333:     }
334:   }
335: 
336:   private sweepControlRequests(): void {
337:     if (!this.controlRequestDirectory || !this.controlResponseDirectory) return;
338:     this.pruneControlFiles();
339:     let entries;
340:     try {
341:       entries = readdirSync(this.controlRequestDirectory, { withFileTypes: true });
342:     } catch {
343:       return;
344:     }
345:     for (const entry of entries) {
346:       if (!entry.isFile() || !entry.name.endsWith(".json")) continue;
347:       const requestPath = join(this.controlRequestDirectory, entry.name);
348:       let request: ProcessControlRequest;
349:       try {
350:         request = JSON.parse(readFileSync(requestPath, "utf8")) as ProcessControlRequest;
351:       } catch {
352:         continue;
353:       }
354:       if (
355:         request.version !== 1 ||
356:         !PROCESS_ID_PATTERN.test(request.request_id) ||
357:         !PROCESS_ID_PATTERN.test(request.process_id) ||
358:         (request.action !== "read" && request.action !== "kill") ||
359:         typeof request.requester_caller_id !== "string" ||
360:         !Number.isFinite(Date.parse(request.deadline_at))
361:       ) {
362:         try { unlinkSync(requestPath); } catch { /* best effort */ }
363:         continue;
364:       }
365:       if (Date.now() > Date.parse(request.deadline_at)) {
366:         try { unlinkSync(requestPath); } catch { /* best effort */ }
367:         continue;
368:       }
369:       if (!this.processes.has(request.process_id) || this.controlRequestsInFlight.has(request.request_id)) continue;
370:       this.controlRequestsInFlight.add(request.request_id);
371:       void this.handleControlRequest(request, requestPath).finally(() => {
372:         this.controlRequestsInFlight.delete(request.request_id);
373:       });
374:     }
375:   }
376: 
377:   private async handleControlRequest(request: ProcessControlRequest, requestPath: string): Promise<void> {
378:     const responsePath = this.controlPath(this.controlResponseDirectory, request.request_id);
379:     if (!responsePath) return;
380:     const observer: TelemetryContext = {
381:       request_id: request.request_id,
382:       caller_id: request.requester_caller_id,
383:     };
384:     const response: ProcessControlResponse = {
385:       version: 1,
386:       request_id: request.request_id,
387:       process_id: request.process_id,
388:       responded_at: new Date().toISOString(),
389:     };
390:     try {
391:       response.result = await withTelemetryContext(observer, async () => request.action === "kill"
392:         ? await this.kill(request.process_id)
393:         : await this.readWithWait(request.process_id, request.max_chars, request.wait_ms));
394:     } catch (error) {
395:       response.error = error instanceof Error ? error.message : String(error);
396:     }
397:     response.responded_at = new Date().toISOString();
398:     try {
399:       this.writeControlFile(responsePath, response);
400:     } finally {
401:       try { unlinkSync(requestPath); } catch { /* requester may have timed out */ }
402:     }
403:   }
404: 
405:   private async requestRemoteControl(
406:     processId: string,
407:     action: "read" | "kill",
408:     observer: TelemetryContext,
409:     maxChars = MAX_READ_CHARS,
410:     waitMs = 0,
411:   ): Promise<Record<string, unknown>> {
412:     if (!this.controlRequestDirectory || !this.controlResponseDirectory || !PROCESS_ID_PATTERN.test(processId)) {
413:       throw new Error(`Unknown process_id: ${processId}`);
414:     }
415:     const requestId = randomUUID();
416:     const boundedWaitMs = Math.max(0, Math.min(waitMs, 10_000));
417:     const timeoutMs = action === "read"
418:       ? boundedWaitMs + CONTROL_HANDOFF_OVERHEAD_MS
419:       : CONTROL_KILL_TIMEOUT_MS;
420:     const deadlineMs = Date.now() + timeoutMs;
421:     const requestPath = this.controlPath(this.controlRequestDirectory, requestId)!;
422:     const responsePath = this.controlPath(this.controlResponseDirectory, requestId)!;
423:     const request: ProcessControlRequest = {
424:       version: 1,
425:       request_id: requestId,
426:       process_id: processId,
427:       action,
428:       requester_caller_id: observer.caller_id ?? "caller_unknown",
429:       requested_at: new Date().toISOString(),
430:       deadline_at: new Date(deadlineMs).toISOString(),
431:       ...(action === "read" ? { max_chars: Math.max(1, Math.min(maxChars, MAX_READ_CHARS)), wait_ms: boundedWaitMs } : {}),
432:     };
433:     this.writeControlFile(requestPath, request);
434:     emitTelemetry({
435:       event: "process_control_handoff_requested",
436:       process_id: processId,
437:       action,
438:       request_id: requestId,
439:     }, observer);
440:     try {
441:       while (Date.now() <= deadlineMs) {
442:         try {
443:           const response = JSON.parse(readFileSync(responsePath, "utf8")) as ProcessControlResponse;
444:           if (response.version !== 1 || response.request_id !== requestId || response.process_id !== processId) {
445:             throw new Error(`Invalid process control response for ${processId}`);
446:           }
447:           if (response.error) throw new Error(response.error);
448:           if (!response.result || typeof response.result !== "object") throw new Error(`Empty process control response for ${processId}`);
449:           emitTelemetry({
450:             event: "process_control_handoff_completed",
451:             process_id: processId,
452:             action,
453:             request_id: requestId,
454:           }, observer);
455:           return response.result;
456:         } catch (error) {
457:           const code = error instanceof Error && "code" in error ? (error as NodeJS.ErrnoException).code : undefined;
458:           if (code !== "ENOENT") throw error;
459:         }
460:         if (action === "read") {
461:           const receipt = this.readReceipt(processId, maxChars);
462:           if (receipt) return receipt;
463:         }
464:         await delay(CONTROL_POLL_MS);
465:       }
466:       emitTelemetry({
467:         event: "process_control_handoff_timeout",
468:         process_id: processId,
469:         action,
470:         request_id: requestId,
471:       }, observer);
472:       throw new Error(`Process owner unavailable for process_id: ${processId}`);
473:     } finally {
474:       try { unlinkSync(requestPath); } catch { /* owner may already have consumed it */ }
475:       try { unlinkSync(responsePath); } catch { /* response may not exist */ }
476:     }
477:   }
478: 
479:   private persistReceipt(state: ProcessState): void {
480:     const path = this.receiptPath(state.id);
481:     if (!path || !state.finishedAt) return;
482:     const command = state.command.slice(0, MAX_COMMAND_REPORT_CHARS);
483:     // Receipts are local evidence, not a transport payload, so they keep the full
484:     // captured buffer. Using MAX_READ_CHARS here would shrink the durable record to the
485:     // transport ceiling and destroy the only proof that a blocked read's process ran.
486:     const stdout = state.stdout.tail(MAX_CAPTURE_CHARS, MAX_CAPTURE_CHARS);
487:     const stderr = state.stderr.tail(MAX_CAPTURE_CHARS, MAX_CAPTURE_CHARS);
488:     const receipt: CompletedProcessReceipt = {
489:       version: 1,
490:       process_id: state.id,
491:       pid: state.pid,
492:       caller_id: state.callerId,
493:       command,
494:       ...(state.command.length > MAX_COMMAND_REPORT_CHARS ? { command_truncated: true as const } : {}),
495:       cwd: state.cwd,
496:       stdout: stdout.text,
497:       stderr: stderr.text,
498:       ...(stdout.truncated ? { stdout_truncated: true as const } : {}),
499:       ...(stderr.truncated ? { stderr_truncated: true as const } : {}),
500:       exit_code: state.exitCode,
501:       signal: state.signal ?? null,
502:       started_at: state.startedAt,
503:       finished_at: state.finishedAt,
504:       ...(state.error ? { error: state.error } : {}),
505:     };
506:     const temporaryPath = `${path}.${process.pid}.${randomUUID()}.tmp`;
507:     try {
508:       writeFileSync(temporaryPath, JSON.stringify(receipt), { encoding: "utf8", flag: "wx" });
509:       renameSync(temporaryPath, path);
510:       this.pruneReceipts();
511:       emitTelemetry({
512:         event: "process_receipt_persisted",
513:         process_id: state.id,
514:         pid: state.pid,
515:         owner_caller_id: state.callerId,
516:       }, state.ownerContext);
517:     } catch (error) {
518:       try { unlinkSync(temporaryPath); } catch { /* best-effort temporary cleanup */ }
519:       emitTelemetry({
520:         event: "process_receipt_error",
521:         process_id: state.id,
522:         pid: state.pid,
523:         owner_caller_id: state.callerId,
524:         error_message: error instanceof Error ? error.message : String(error),
525:       }, state.ownerContext);
526:     }
527:   }
528: 
529:   private readReceipt(processId: string, maxChars: number): Record<string, unknown> | undefined {
530:     const path = this.receiptPath(processId);
531:     if (!path) return undefined;
532:     this.pruneReceipts();
533:     let receipt: CompletedProcessReceipt;
534:     try {
535:       receipt = JSON.parse(readFileSync(path, "utf8")) as CompletedProcessReceipt;
536:     } catch {
537:       return undefined;
538:     }
539:     if (receipt.version !== 1 || receipt.process_id !== processId || typeof receipt.pid !== "number" || typeof receipt.command !== "string" || typeof receipt.cwd !== "string" || typeof receipt.stdout !== "string" || typeof receipt.stderr !== "string" || typeof receipt.started_at !== "string" || typeof receipt.finished_at !== "string") {
540:       return undefined;
541:     }
542:     const limit = Math.max(1, Math.min(maxChars, MAX_READ_CHARS));
543:     const stdout = receipt.stdout.slice(-limit);
544:     const stderr = receipt.stderr.slice(-limit);
545:     const observer = currentTelemetryContext();
546:     emitTelemetry({
547:       event: "process_receipt_read",
548:       process_id: receipt.process_id,
549:       pid: receipt.pid,
550:       owner_caller_id: receipt.caller_id,
551:       caller_id: observer.caller_id ?? "caller_unknown",
552:     }, observer);
553:     return {
554:       ...processResponseState(receipt.started_at, false, receipt.finished_at),
555:       process_id: receipt.process_id,
556:       pid: receipt.pid,
557:       command: receipt.command,
558:       ...(receipt.command_truncated ? { command_truncated: true } : {}),
559:       cwd: receipt.cwd,
560:       running: false,
561:       stdout,
562:       stderr,
563:       exit_code: receipt.exit_code,
564:       signal: receipt.signal,
565:       started_at: receipt.started_at,
566:       finished_at: receipt.finished_at,
567:       ...(receipt.stdout_truncated || receipt.stdout.length > limit ? { stdout_truncated: true } : {}),
568:       ...(receipt.stderr_truncated || receipt.stderr.length > limit ? { stderr_truncated: true } : {}),
569:       ...(receipt.error ? { error: receipt.error } : {}),
570:     };
571:   }
572: 
573:   private reserveLaunch(callerId: string): void {
574:     const now = this.now();
575:     const bucket = this.launchBucketsByCaller.get(callerId) ?? {
576:       tokens: this.launchBucketCapacity,
577:       lastRefillAt: now,
578:     };
579:     const elapsedMs = Math.max(0, now - bucket.lastRefillAt);
580:     bucket.tokens = Math.min(
581:       this.launchBucketCapacity,
582:       bucket.tokens + elapsedMs / this.launchRefillMs,
583:     );
584:     bucket.lastRefillAt = now;
585:     if (bucket.tokens < 1) {
586:       const retryAfterMs = Math.max(1, Math.ceil((1 - bucket.tokens) * this.launchRefillMs));
587:       this.launchBucketsByCaller.set(callerId, bucket);
588:       throw new Error(`start_process_rate_limited: caller launch bucket is empty; capacity=${this.launchBucketCapacity}; refill_ms=${this.launchRefillMs}; retry_after_ms=${retryAfterMs}`);
589:     }
590:     bucket.tokens -= 1;
591:     this.launchBucketsByCaller.set(callerId, bucket);
592:   }
593: 
594:   private markProcessChanged(state: ProcessState): void {
595:     state.revision += 1;
596:     for (const wake of [...state.waiters]) wake();
597:   }
598: 
599:   private pruneCompleted(): void {
600:     const now = Date.now();
601:     const completed = [...this.processes.values()]
602:       .filter((state) => state.exitCode !== null && state.finishedAt)
603:       .sort((a, b) => Date.parse(a.finishedAt!) - Date.parse(b.finishedAt!));
604:     for (const state of completed) {
605:       const expired = now - Date.parse(state.finishedAt!) > COMPLETED_RETENTION_MS;
606:       if (expired) this.processes.delete(state.id);
607:     }
608:     const remaining = [...this.processes.values()]
