  });
  const output = await new Promise((resolveResult, rejectResult) => {
    let stdout = "";
    let stderr = "";
    smoke.stdout.on("data", (chunk) => { stdout += chunk.toString(); });
    smoke.stderr.on("data", (chunk) => { stderr += chunk.toString(); });
